sys_ws_operation.operation_script:
(function process(request, response) {

    // =========================================================
    // 1. GET LOGGED-IN EMPLOYEE
    // =========================================================
    var employeeId = gs.getUserID();


    // =========================================================
    // 2. READ TOKEN
    // =========================================================
    var token = request.queryParams.token;


    if (!token) {

        response.setStatus(400);

        response.setBody({
            success: false,
            message: 'QR token is required'
        });

        return;
    }


    // =========================================================
    // 3. FIND TOKEN BELONGING TO THIS EMPLOYEE
    // =========================================================
    var qr = new GlideRecord(
        'x_1760545_smarta_0_qr_token'
    );

    qr.addQuery('token', token);
    qr.addQuery('employee', employeeId);
    qr.setLimit(1);
    qr.query();


    if (!qr.next()) {

        response.setStatus(404);

        response.setBody({
            success: false,
            message: 'QR token not found'
        });

        return;
    }


    var tokenStatus =
        qr.getValue('status');


    // =========================================================
    // 4. ACTIVE TOKEN
    // =========================================================
    if (tokenStatus == 'active') {

        var now =
            new GlideDateTime();

        var expiresAt =
            new GlideDateTime(
                qr.getValue('expires_at')
            );


        if (
            expiresAt.getNumericValue() <
            now.getNumericValue()
        ) {

            qr.setValue(
                'status',
                'expired'
            );

            qr.update();


            response.setStatus(200);

            response.setBody({
                success: true,
                token_status: 'expired'
            });

            return;
        }


        response.setStatus(200);

        response.setBody({
            success: true,
            token_status: 'active'
        });

        return;
    }


    // =========================================================
    // 5. EXPIRED / CANCELLED
    // =========================================================
    if (
        tokenStatus == 'expired' ||
        tokenStatus == 'cancelled'
    ) {

        response.setStatus(200);

        response.setBody({
            success: true,
            token_status: tokenStatus
        });

        return;
    }


    // =========================================================
    // 6. USED TOKEN
    // =========================================================
    if (tokenStatus == 'used') {

        var attendanceId =
            qr.getValue('attendance');

        var result = {

            success: true,

            token_status: 'used',

            action:
                qr.getValue('scan_action'),

            scanner:
                qr.used_by_scanner
                    .getDisplayValue(),

            used_at:
                qr.getValue('used_at')
        };


        // -----------------------------------------------------
        // Get Attendance details
        // -----------------------------------------------------
        if (attendanceId) {

            var attendance =
                new GlideRecord(
                    'x_1760545_smarta_0_attendance'
                );


            if (
                attendance.get(
                    attendanceId
                )
            ) {

                result.attendance_id =
                    attendance.getUniqueValue();

                result.employee =
                    attendance.employee
                        .getDisplayValue();

                result.status =
                    attendance.getValue(
                        'status'
                    );

                result.late_minutes =
                    attendance.getValue(
                        'late_minutes'
                    );

                result.working_minutes =
                    attendance.getValue(
                        'working_minutes'
                    );

                result.check_in =
                    attendance.getValue(
                        'check_in'
                    );

                result.check_out =
                    attendance.getValue(
                        'check_out'
                    );
            }
        }


        response.setStatus(200);

        response.setBody(result);

        return;
    }


    // =========================================================
    // 7. FALLBACK
    // =========================================================
    response.setStatus(200);

    response.setBody({
        success: true,
        token_status:
            tokenStatus || 'unknown'
    });

})(request, response);
